def transform(grid):
    h, w = len(grid), len(grid[0])
    border = grid[0][0]
    step = next(r for r in range(1, h) if all(x == border for x in grid[r]))
    nr, nc = h // step, w // step
    background = grid[1][1]
    out = [row[:step+1] for row in grid]
    for r in range(nr):
        for c in range(1, nc):
            for y in range(step):
                for x in range(step+1):
                    value = grid[r*step+y][c*step+x]
                    if value != background:
                        out[r*step+y][x] = value
    return out

